sys_ui_action.script:
function moveCurrentToPending() {
    g_form.setValue('pending_status', g_form.getValue('install_status'));
    g_form.setValue('pending_name', g_form.getValue('name'));
    g_form.setValue('pending_client_id', g_form.getValue('client_id'));
    g_form.setValue('pending_local_circuit_id', g_form.getValue('local_circuit_id'));
    g_form.setValue('pending_ip_address', g_form.getValue('ip_address'));
    g_form.setValue('pending_pe_host_circuit_id', g_form.getValue('pe_host_circuit_id'));
    g_form.setValue('pending_vrf', g_form.getValue('vrf'));
    g_form.setValue('pending_master_device_interface', g_form.getValue('master_device_interface'));
    g_form.setValue('pending_description', g_form.getValue('description'));
    g_form.setValue('pending_type', g_form.getValue('type'));
    g_form.setValue('pending_remote_site_circuit_vlan', g_form.getValue('remote_site_circuit_vlan'));
    g_form.setValue('pending_interface_subnet_mask', g_form.getValue('interface_subnet_mask'));
    g_form.setValue('pending_network_gear', g_form.getValue('network_gear'));
    g_form.setValue('pending_uplink_connection_description', g_form.getValue('uplink_connection_description'));
    g_form.save();
}
